CREATE TABLE IF NOT EXISTS partners(id UUID PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'pt-AO',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,partner_id UUID NOT NULL REFERENCES partners(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS properties(id UUID PRIMARY KEY,partner_id UUID NOT NULL REFERENCES partners(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL,province TEXT NOT NULL,city TEXT NOT NULL,neighborhood TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',bedrooms INTEGER NOT NULL,bathrooms NUMERIC NOT NULL,guest_capacity INTEGER NOT NULL,area_square_meters INTEGER NOT NULL,floor TEXT,amenities JSONB NOT NULL DEFAULT '[]',description TEXT NOT NULL,nightly_rate INTEGER NOT NULL CHECK(nightly_rate>=0),status TEXT NOT NULL CHECK(status IN ('published','draft')),rating NUMERIC NOT NULL DEFAULT 0,review_count INTEGER NOT NULL DEFAULT 0,occupancy_rate NUMERIC NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_photos(id UUID PRIMARY KEY,property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,url TEXT NOT NULL,alt_text TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guests(id UUID PRIMARY KEY,partner_id UUID NOT NULL REFERENCES partners(id) ON DELETE CASCADE,name TEXT NOT NULL,contact TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(partner_id,contact));
CREATE TABLE IF NOT EXISTS reservations(id UUID PRIMARY KEY,reference TEXT NOT NULL UNIQUE,partner_id UUID NOT NULL REFERENCES partners(id) ON DELETE CASCADE,property_id UUID NOT NULL REFERENCES properties(id),guest_id UUID NOT NULL REFERENCES guests(id),check_in DATE NOT NULL,check_out DATE NOT NULL,guest_count INTEGER NOT NULL,night_count INTEGER NOT NULL,nightly_rate INTEGER NOT NULL,total_amount INTEGER NOT NULL,payment_method TEXT NOT NULL,invoice_requested BOOLEAN NOT NULL DEFAULT false,channel TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','confirmed','checked_in','completed','cancelled')),cancellation_reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(check_out>check_in));
CREATE TABLE IF NOT EXISTS booking_links(id UUID PRIMARY KEY,token TEXT NOT NULL UNIQUE,partner_id UUID NOT NULL REFERENCES partners(id) ON DELETE CASCADE,property_id UUID NOT NULL REFERENCES properties(id),check_in DATE NOT NULL,check_out DATE NOT NULL,guest_count INTEGER NOT NULL,channel TEXT NOT NULL,guest_contact TEXT,nightly_rate INTEGER NOT NULL,estimated_total INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','submitted','expired','revoked')),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(check_out>check_in));
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY,reference TEXT NOT NULL UNIQUE,reservation_id UUID NOT NULL REFERENCES reservations(id) ON DELETE CASCADE,partner_id UUID NOT NULL REFERENCES partners(id) ON DELETE CASCADE,date DATE NOT NULL,amount INTEGER NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','processing','paid','failed','refunded')),is_demo BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS settings(partner_id UUID PRIMARY KEY REFERENCES partners(id) ON DELETE CASCADE,booking_notifications BOOLEAN NOT NULL DEFAULT true,payment_notifications BOOLEAN NOT NULL DEFAULT true);
CREATE INDEX IF NOT EXISTS idx_properties_partner_status ON properties(partner_id,status);
CREATE INDEX IF NOT EXISTS idx_res_partner_status_dates ON reservations(partner_id,status,check_in,check_out);
CREATE INDEX IF NOT EXISTS idx_res_guest_property ON reservations(guest_id,property_id);
CREATE INDEX IF NOT EXISTS idx_guests_partner ON guests(partner_id);
CREATE INDEX IF NOT EXISTS idx_payments_partner_status_date ON payments(partner_id,status,date);
CREATE INDEX IF NOT EXISTS idx_photos_property_order ON property_photos(property_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_links_partner_status_exp ON booking_links(partner_id,status,expires_at);
